export type ExperimentSlug =
  | "cosmic-glow"
  | "chain-picker"
  | "building-glass-for-the-web"
  | "glass-video-player"
  | "glass-qr-code"
  | "glass-switch"
  | "glass-range-slider"
  | "glass-toggle-group"
  | "bloom-icons"
  | "shimmering-dots"
  | "family-color-picker"
  | "family-otp-input"
